package com.styleshop.auth.service;
import com.styleshop.auth.model.User; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.stereotype.Service; import java.time.Instant;
@Service public class JwtService { private final JwtEncoder encoder; private final long seconds; private final String issuer; public JwtService(JwtEncoder e,@Value("${styleshop.jwt.expires-in-seconds:1800}")long s,@Value("${styleshop.jwt.issuer:styleshop-auth}")String i){encoder=e;seconds=s;issuer=i;} public String create(User u){var now=Instant.now();var claims=JwtClaimsSet.builder().issuer(issuer).issuedAt(now).expiresAt(now.plusSeconds(seconds)).subject(u.getUsername()).claim("roles",u.getRole()).build();var header=JwsHeader.with(SignatureAlgorithm.RS256).type("JWT").build();return encoder.encode(JwtEncoderParameters.from(header,claims)).getTokenValue();} public long expires(){return seconds;} }
